<?php
require_once 'config.php'; exigirLogin();
if (!temPerfil('admin')) { http_response_code(403); exit('Acesso restrito aos administradores.'); }
try {
    $metricas = ['usuarios' => (int) $pdo->query('SELECT COUNT(*) FROM usuarios WHERE ativo = TRUE')->fetchColumn(), 'treinamentos' => (int) $pdo->query('SELECT COUNT(*) FROM treinamentos')->fetchColumn(), 'aulas' => (int) $pdo->query('SELECT COUNT(*) FROM aulas')->fetchColumn(), 'pendentes' => (int) $pdo->query("SELECT COUNT(*) FROM treinamentos WHERE status = 'rascunho'")->fetchColumn(), 'materiais' => (int) $pdo->query('SELECT COUNT(*) FROM materiais')->fetchColumn()];
    $atividades = $pdo->query("SELECT u.nome, 'criou o treinamento' AS acao, t.titulo AS item, t.criado_em FROM treinamentos t JOIN usuarios u ON u.id = t.criado_por UNION ALL SELECT u.nome, 'enviou uma solicitação' AS acao, 'pedido de suporte' AS item, s.criado_em FROM pedidos_suporte s JOIN usuarios u ON u.id = s.usuario_id ORDER BY criado_em DESC LIMIT 8")->fetchAll();
    $suportes = $pdo->query("SELECT s.id, u.nome, u.email, s.mensagem, s.criado_em FROM pedidos_suporte s JOIN usuarios u ON u.id = s.usuario_id WHERE s.status = 'pendente' ORDER BY s.criado_em DESC LIMIT 5")->fetchAll();
} catch (Throwable $e) { error_log('TrainHub admin dashboard query failed: ' . $e->getMessage()); $metricas = array_fill_keys(['usuarios','treinamentos','aulas','pendentes','materiais'], 0); $atividades = []; $suportes = []; }
?><!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TrainHub - Dashboard Administrativo</title><script src="https://cdn.tailwindcss.com"></script><style>body{background:#273143}.card{background:#3b475e}.tile{background:#202838}.muted{color:#aeb8ca}</style></head><body class="min-h-screen text-white"><header class="h-14 bg-gray-800 flex items-center justify-between px-5"><a href="dashboard.php" class="text-blue-400 font-bold text-xl">TrainHub</a><span class="rounded-xl bg-slate-700 px-4 py-2">Dashboard</span><a href="logout.php" class="rounded-full bg-black w-8 h-8" aria-label="Sair"></a></header><main class="max-w-6xl mx-auto p-5 md:p-8"><a href="dashboard.php" class="text-2xl">←</a><section class="grid grid-cols-2 md:grid-cols-5 gap-3 my-5"><?php foreach (['usuarios'=>'Usuários','treinamentos'=>'Treinamentos','aulas'=>'Aulas','pendentes'=>'Pendentes','materiais'=>'Materiais'] as $tipo => $rotulo): ?><a href="admin-gerenciar.php?tipo=<?php echo $tipo; ?>" class="tile rounded-xl p-4 text-center hover:bg-slate-600"><strong class="block text-base"><?php echo $rotulo; ?></strong><span class="text-xl font-bold"><?php echo $metricas[$tipo]; ?></span></a><?php endforeach; ?></section><div class="grid lg:grid-cols-2 gap-5"><section class="card rounded-2xl overflow-hidden"><h2 class="tile p-4 font-bold">Atividades recentes</h2><div class="p-4 space-y-2"><?php if (!$atividades): ?><p class="muted">Nenhuma atividade registrada.</p><?php endif; ?><?php foreach ($atividades as $atividade): ?><p class="tile rounded-lg p-3 text-sm">- <?php echo esc($atividade['nome']); ?> <?php echo esc($atividade['acao']); ?> “<?php echo esc($atividade['item']); ?>”<br><small class="muted"><?php echo esc($atividade['criado_em']); ?></small></p><?php endforeach; ?></div></section><section class="card rounded-2xl overflow-hidden"><h2 class="tile p-4 font-bold">Pedidos de suporte</h2><div class="p-4 space-y-2"><?php if (!$suportes): ?><p class="muted">Nenhum pedido de suporte pendente.</p><?php else: ?><?php foreach ($suportes as $suporte): ?><article class="tile rounded-lg p-3 text-sm"><strong><?php echo esc($suporte['nome']); ?></strong><p class="muted"><?php echo esc($suporte['email']); ?></p><p class="mt-2"><?php echo esc($suporte['mensagem']); ?></p></article><?php endforeach; ?><?php endif; ?></div></section></div><div class="flex gap-3 mt-6"><a href="usuarios.php" class="rounded-lg bg-blue-700 px-4 py-2">Gerenciar usuários</a><a href="logout.php" class="rounded-lg bg-slate-700 px-4 py-2">Sair</a></div></main></body></html>
